nb_dio_get.example:
val = nb_dio_get("in1");
if (val == 1) {
    printf("Input 1 is HIGH\n");
}

nb_dio_set.example:
// Turn on output port 1
nb_dio_set("out1", 1);
sleep(2);
nb_dio_set("out1", 0);

nb_status.example:
loc = nb_status("location");
if (!is_void(loc)) {
    printf("Lat: %s, Lon: %s\n", loc.LOCATION_LATITUDE, loc.LOCATION_LONGITUDE);
}

nb_ping.example:
rtt = nb_ping("8.8.8.8", 3);
if (rtt >= 0) {
    printf("Ping OK: %d ms\n", rtt);
}

nb_sms_recv.example:
messages = nb_sms_recv(0);
for (i = 0; i < length(messages); i++) {
    dump(messages[i]);
}

nb_cellular_scan.example:
ops = nb_cellular_scan("mobile0");
for (i = 0; i < length(ops); i++) {
    printf("PLMN: %s, Name: %s\n", ops[i].PLMN, ops[i].NAME);
}

nb_gps_status.example:
gps = nb_gps_status();
if (gps.FIX) {
    printf("Position: %s, %s\n", gps.LATITUDE, gps.LONGITUDE);
}

template.example:
template Device {
    id = 0;
    name = "";
    Device(id, name) {
        this.id = id;
        this.name = name;
    }
    print_info() {
        printf("Device %s (#%d)\n", this.name, this.id);
    }
}

forced.example:
int add(forced int a, forced int b) {
    return a + b;
}

try.example:
try {
    risky_operation();
} catch (e) {
    printf("Error caught: %s\n", e);
}

switch.example:
switch (cmd) {
    case 1: start(); break;
    default: stop();
}

snippets.insertText:
f = fopen(${1:path}, "r");
if (!is_void(f)) {
	content = fread(f, file_size(${1:path}));
	fclose(f);
	${0}
}
